package com.nextrade.service; import java.time.*; import java.util.concurrent.*; import java.util.concurrent.atomic.*; public final class InMemoryRateLimitStore implements RateLimitStore {private record Bucket(AtomicLong count,Instant expiresAt){}private final ConcurrentHashMap<String,Bucket> buckets=new ConcurrentHashMap<>();public RateLimitDecision tryConsume(String key,int capacity,Duration window){Instant now=Instant.now();Bucket b=buckets.compute(key,(k,old)->old==null||old.expiresAt().isBefore(now)?new Bucket(new AtomicLong(0),now.plus(window)):old);long n=b.count().incrementAndGet();if(n<=capacity)return RateLimitDecision.allow(capacity-n);return RateLimitDecision.deny(b.expiresAt());}}
